		id: 'missile_smart_heavy_mk1',
		version: 0,
		name: 'Heavy Smart Missile Mk1',
		description: 'The Heavy Smart missile was an ATF project intended to complement the smaller and slightly more agile Light Smart system. Where the Light Smart missile would be used against the agile fighters and heavy fighters of the Xenon, the Heavy Smart missile was meant for heavy fighters and light to medium corvette-sized ships. Like its smaller counterpart, the Heavy Smart missile also required the same focus on friend-foe discrimination capability, but its warhead would be scaled up in order to more effectively handle the larger types of targets it was intended for use against. Unfortunately, the weapon system suffered the same fate as the Light Smart missile; the ATF stopped development in favour of more promising weapon systems and the technology remained dormant for many decades before research was continued by an intrepid Argon scientist, who obtained the schematics from an undercover agent.',
