		version: 0,
		name: 'Heavy Swarm Missile Mk1',
		description: 'The bigger sister to the Light Swarm missile, the Heavy Swarm version is also a Paranid weapon system designed to overcome defensive anti-missile measures on a well equipped target. Like its smaller counterpart, the Heavy Swarm missile uses a two-stage solution to achieve this. A larger primary stage consists of an external shell that carries multiple, smaller missiles internally. The outer shell ensures compliance with standardised launchers, and the internally carried sub-missiles are released just a few seconds after launch. At that point, they disperse and follow an infra-red spectrum guidance laser from the launching ship to the intended target. The use of the laser makes the system somewhat cheaper, which helps offset the cost of several guidance sections, but also makes the weapon susceptible to infra-red decoys such as flares.nnThe sub-missiles are fitted with fairly powerful high-explosive warheads behind a teladianium disc. When triggered, the teladianium forms into a shape somewhat like a dart. This dart penetrates into the target where it fractures into large, devastating shards of almost molten metal, causing tremendous damage.',
