		id: 'missile_torpedo_heavy_mk1',
		version: 0,
		name: 'Heavy Torpedo Missile Mk1',
		description: 'The Heavy Torpedo missile is more commonly known as the Triton. Torpedoes are significantly slower than other missile weapons but they provide far and away more firepower on impact than any other type. They are best utilised, therefore, against less agile ships and emplacements that cannot easily avoid the impact simply by moving out of the way. Significantly more powerful than the Light Torpedo missile, this weapon is the premier choice against the heaviest and most durable of hostile vessels. No other weapon delivers as much destructive power as the Triton in a single explosive blast. The Triton missile is a hot-launched weapon. This means the rocket motor fires immediately upon button-press and begins its slow, ponderous journey towards the target. This in turn imparts significantly more stress and maintenance costs upon the launcher itself. Like its smaller counterpart, the Light Torpedo missile, the Triton is extremely resilient to countermeasures.',
