		description: 'Torpedoes are significantly slower than other missile weapons but they provide far and away more firepower on impact than any other type. They are best utilised, therefore, against less agile ships and emplacements that cannot easily avoid the impact simply by moving out of the way. The Light Torpedo missile is a hot-launched weapon. This means the rocket motor fires immediately upon button-press and begins its slow, ponderous journey towards the target. This in turn imparts significantly more stress and maintenance costs upon the launcher itself. With an enlarged launcher comes a larger body which allows significantly more room for explosive mass in the weapon. This torpedo is a two-stage weapon with a powerful high explosive precursor warhead that violently rips a hole in the enemy vessel. A primary charge then detonates and turns the weapon into a massive and extremely damaging fragmentation grenade, more than powerful enough to rip apart most ships in a single blow. The Light Torpedo missile is extremely resilient to countermeasures.',
