		version: 0,
		name: 'M Beam Emitter Mk1',
		description: 'The Beam Emitter is a highly specialised anti-fighter weapon, notable for its high accuracy. It discharges high-velocity beams which hit their target almost immediately. However, somewhat counterintuitively, it achieves this instantaneous accuracy by restraining the energy that the beam puts out. Since the beam is not as intense as the projectiles fired by many of its counterparts, it only inflicts damage gradually, which exposes the pilot to a counter-attack. Because of this, the Beam Emitter is mainly used on nimble fighters, which are able to get up close and out-manoeuvre their target when necessary.nnThe Mk2 variant tries to rectify the weak damage output somewhat, by ramping up the beam\'s intensity, but this comes at the cost of the weapon overheating more rapidly.',
