		version: 0,
		name: 'TEL M Muon Charger Mk2',
		description: 'The Muon Charger is a short range, high damage weapon. Its unusual handling requires the pilot to manually charge every shot. It is recommended that it only be used when fully charged, as the damage potential is otherwise greatly reduced. Upon release, it fires multiple bolts, with a relatively small spread, which are able to stick to a target and deal damage over time. Earlier iterations had an issue with the priming of the weapon, causing some of its projectiles to ricochet harmlessly. This has since been rectified, improving the reliability of this weapon in the heat of battle. If used correctly, the Muon Charger will never overheat, allowing for a continuous and consistent damage output.nnThe Ministry of Finance Science Division developed this weapon for all-round use, though arguably it can be difficult to deploy effectively in dogfights against fast targets. The ability to hold the charge and release at will was intended to give pilots more control over their weapon, and increase the fighter fleet\'s accuracy statistics. The unique characteristics of this weapon, however, mean that custom training is required, making it unsuitable for the Ministry\'s novice fighter program.nnThe Mk2 variant offers increased damage output.',
		race: Races.teladi,
		type: EquipmentType.weapons,
		equipmentClass: EquipmentClass.weapon,
		size: Size.medium,
