		id: 'missile_scatter_heavy_mk1',
		version: 1,
		name: 'Heavy Scatter Missile Mk1',
		description: 'The Heavy Scatter missile is a two-stage weapon. In order to fit within the fixed dimensions of standard launchers, a compromise had to be found in order to provide a rapid-fire solution using rockets as ammunition in place of ordinary gun systems. The weapon contains a primary stage which consists of an outer, detachable shell and internal wiring as well as the necessary attachment points for housing several individual rockets. Once the weapon has cleared the launcher and the main body is at a safe distance from the ship, the outer shell will detach from the internal rigging into four separate pieces. In a matter of microseconds the smaller individual rockets detach from the internal rigging and their boosters ignite, propelling them towards the target at speed. The weapon behaves much like a very complex shotgun, albeit a shotgun that fires rockets instead of pellets.nnUsing a combination of high explosive and incendiary warheads can inflict widespread damage to multiple separate points on an enemy combatant, and is a very effective way of overpowering their damage control capabilities. It is, however, extremely inaccurate and should be used only from point-blank range against L and XL targets.',
