		version: 1,
		name: 'Heavy Starburst Missile Mk1',
		description: 'The Starburst, whose name comes from its peculiar warhead, is a missile that embodies the Split mentality of hitting hard. So hard in fact, that by some measures, it carries arguably the most powerful warhead available for any missile weapon shy of a torpedo-class munition. The incredible destructive power of the weapon, along with its classification, has been the source of no small number of legal disputes between the Split, seeking to keep it as a missile for export purposes, and certain non-Split wishing to have it reclassified as a Torpedo for their own benefit.nnThe Starburst uses a special kind of fuel, in the form of a continuous rod that extends through almost the entire length of the weapon. This rod serves as both fuel for the engine, and as the source of its destructive potential. The rate of combustion is kept under control by spraying the fuel-rod with a dampener-agent, without which the burn-rate spirals out of control much in the same way as a star going supernova, albeit on a much smaller scale.',
