		description: 'The Gamma HEPT was developed as a cutting-edge weapon and represents a pioneering advancement in plasma weaponry. This weapon epitomises the fusion of innovation and practicality, designed to provide unparalleled firepower in the unforgiving depths of space. Drawing upon the fundamental principles of plasma manipulation, the Gamma HEPT projects a torrent of searing energy spheres with devastating force.nnWhile future iterations on this same design improve and refine the concept, this early version is perhaps the most important. It marks the point at which the balance of power and reliability was such that it became a truly formidable weapon as opposed to a purely experimental one.',
